<script setup>
import { computed, inject, onBeforeUnmount, proxyRefs, reactive, ref, watch } from 'vue';
import { useController } from '../../components/AdminBarSection.vue?admin-v2-controller';
import V2Panel from '../components/shared/V2Panel.vue';
import V2Dialog from '../components/shared/V2Dialog.vue';
const c = inject('admin-v2');
const props = reactive({ authHeaders: computed(() => c.authHeaders), isSuperAdmin: computed(() => c.isSuperAdmin) });
const loadError = ref('');
let disposed = false;
onBeforeUnmount(() => { disposed = true; });
const b = proxyRefs(useController(props, () => {}, {
 isDisposed: () => disposed,
 onLifecycleComplete: () => { loadError.value = ''; },
 onLifecycleError: error => { if (!disposed) loadError.value = error?.response?.data?.message || 'Impossibile caricare il bar. Riprova.'; },
}));
const metricCards = computed(() => b.activeTab === 'stats' ? b.statsCards : b.activeTab === 'cash' ? b.cashCards : b.kpis);
const suggestionScope = ref('products');
const suggestionEntities = computed(() => suggestionScope.value === 'products' ? b.productCards : b.barCategories);
function suggestion(entity) { return suggestionScope.value === 'products' ? b.productSuggestionState(entity.id) : b.categorySuggestionState(entity.id); }
function patchSuggestion(entity, key, value) {
  const patch = { [key]: key === 'max_items' ? Number(value) : value };
  if (suggestionScope.value === 'products') b.patchProductSuggestion(entity.id, patch); else b.patchCategorySuggestion(entity.id, patch);
}
function toggleSuggestion(entity, candidate, checked) {
  if (suggestionScope.value === 'products') b.toggleProductSuggestion(entity.id, candidate.id, checked); else b.toggleCategorySuggestion(entity.id, candidate.id, checked);
}
function saveSuggestion(entity) { return c.run(`bar-suggestion-${entity.id}`, () => suggestionScope.value === 'products' ? b.saveProductSuggestion(entity.id) : b.saveCategorySuggestion(entity.id), 'Suggerimenti salvati.'); }
function refresh() { return c.run('bar-refresh', () => b.retryLifecycle()); }
function remove(type, entity) {
 const actions = { product: b.deleteProduct, menu: b.deleteMenu, category: b.deleteCategory };
 c.confirmAction('Eliminare questo elemento?', `“${entity.name}” verrà eliminato dal catalogo bar.`, () => c.run(`bar-delete-${type}-${entity.id}`, () => actions[type](entity.id), 'Elemento eliminato.'));
}
function changeStatus(order, status) {
 const save = () => c.run(`bar-order-${order.id}`, () => b.setStatus(order.id, status), 'Stato ordine aggiornato.');
 if (status === 'annullato') c.confirmAction(`Annullare l’ordine #${order.id}?`, 'L’ordine verrà contrassegnato come annullato.', save); else save();
}
function latestDetail(order) { b.openOrderDetail(b.parsedOrders.find(item => item.id === order.id) || { ...order, parsedItems: b.parseItems(order) }); }
watch(() => c.route?.detail, value => { if (value && b.tabs.some(tab => tab.id === value)) b.activeTab = value; }, { immediate: true });
</script>

<template>
 <div class="v2-stack v2-bar">
  <div class="v2-toolbar v2-bar-summary"><div><h2>Servizio bar</h2><p class="v2-muted">{{ c.organizationName || c.organizationSlug }} · Aggiornamento: {{ b.lastRefreshAt ? b.lastRefreshLabel : 'in attesa dei dati' }}</p></div><button class="v2-button" :disabled="b.isLoading || c.busy('bar-refresh')" @click="refresh">{{ b.isLoading ? 'Aggiornamento…' : 'Aggiorna dati' }}</button></div>
  <nav class="v2-tabs" aria-label="Aree del bar"><button v-for="tab in b.tabs" :key="tab.id" :aria-current="b.activeTab === tab.id ? 'page' : undefined" @click="b.activeTab = tab.id">{{ tab.label }}</button></nav>
  <div v-if="loadError" class="v2-error" role="alert">{{ loadError }} <button class="v2-link" @click="refresh">Riprova</button></div>
  <div v-if="b.isLoading && !b.lastRefreshAt" class="v2-grid-4" aria-label="Caricamento bar"><div v-for="index in 4" :key="index" class="v2-skeleton" /></div>

  <template v-if="['dashboard','stats','cash'].includes(b.activeTab)">
   <div v-if="b.lastRefreshAt" class="v2-grid-4"><article v-for="metric in metricCards" :key="metric.label" class="v2-metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong></article></div>
   <V2Panel v-if="b.activeTab === 'dashboard'" title="Ultimi ordini" description="Situazione operativa restituita dal servizio bar.">
    <template #actions><button class="v2-button v2-primary" @click="b.activeTab = 'live'">Apri ordini live</button></template>
    <div v-if="!(b.overview.latest_orders || []).length" class="v2-empty">Nessun ordine recente.</div>
    <div v-else class="v2-table-wrap"><table class="v2-table"><thead><tr><th>Ordine</th><th>Stato</th><th>Totale</th><th>Posizione</th><th><span class="v2-muted">Azioni</span></th></tr></thead><tbody><tr v-for="order in b.overview.latest_orders" :key="order.id"><td><strong>#{{ order.id }}</strong></td><td>{{ b.statusLabel(order.order_status) }}</td><td>€ {{ b.euro(order.total_cents) }}</td><td>{{ b.seatingLabel(order) }}</td><td><button class="v2-link" @click="latestDetail(order)">Dettaglio</button></td></tr></tbody></table></div>
   </V2Panel>
   <V2Panel v-if="b.activeTab === 'stats'" title="Prodotti più venduti" description="Riepilogo calcolato sugli ordini disponibili, secondo la logica esistente."><div v-if="!b.topProducts.length" class="v2-empty">Nessun dato di vendita disponibile.</div><div v-for="item in b.topProducts" :key="item.id" class="v2-bar-row"><strong>{{ item.name }}</strong><span class="v2-badge">{{ item.qty }} pezzi</span></div></V2Panel>
   <p v-if="b.activeTab === 'cash'" class="v2-notice">Questo riepilogo utilizza gli ordini restituiti dal servizio. Non registra una chiusura contabile.</p>
  </template>

  <template v-else-if="b.activeTab === 'live'">
   <p class="v2-muted">Gli ordini si aggiornano ogni 15 secondi quando l’aggiornamento automatico è attivo.</p>
   <div class="v2-bar-board"><section v-for="column in b.liveColumns" :key="column.id" class="v2-bar-column"><header class="v2-toolbar"><h3>{{ column.title }}</h3><span class="v2-badge">{{ column.orders.length }}</span></header><p v-if="!column.orders.length" class="v2-empty">{{ column.emptyText }}</p>
    <article v-for="order in column.orders" :key="order.id" class="v2-bar-order" :class="{ 'v2-bar-urgent': order.elapsedMinutes >= 18, 'v2-bar-attention': order.elapsedMinutes >= 10 && order.elapsedMinutes < 18 }">
     <header class="v2-toolbar"><button class="v2-link" @click="b.openOrderDetail(order)">Ordine #{{ order.id }}</button><span class="v2-badge" :class="order.elapsedMinutes >= 18 ? 'danger' : order.elapsedMinutes >= 10 ? 'warning' : ''">{{ order.elapsedMinutes }} min</span></header>
     <p class="v2-muted">{{ b.formatOrderTime(order.created_at) }} · {{ b.customerLabel(order) }}</p><p><strong>€ {{ b.euro(order.total_cents) }}</strong> · {{ b.seatingLabel(order) }}</p><span class="v2-badge" :class="b.paymentClass(order.payment_status) === 'ok' ? 'success' : 'warning'">{{ b.paymentLabel(order.payment_status) }}</span>
     <ul class="v2-bar-items"><li v-for="item in order.parsedItems" :key="item.id"><strong>{{ item.quantity }} ×</strong> {{ item.name }}</li></ul><p v-if="order.notes" class="v2-notice">{{ order.notes }}</p>
     <footer class="v2-stack"><button v-if="b.nextStatusAction(order.order_status)" class="v2-button v2-primary" :disabled="c.busy(`bar-order-${order.id}`)" @click="changeStatus(order, b.nextStatusAction(order.order_status).status)">{{ b.nextStatusAction(order.order_status).label }}</button><div class="v2-toolbar"><button v-if="b.canCancel(order.order_status)" class="v2-button v2-danger" :disabled="c.busy(`bar-order-${order.id}`)" @click="changeStatus(order, 'annullato')">Annulla ordine</button><button class="v2-button" @click="b.openOrderDetail(order)">Dettaglio</button></div></footer>
    </article>
   </section></div>
  </template>

  <V2Panel v-else-if="b.activeTab === 'history'" title="Storico ordini">
   <div class="v2-grid-3"><label class="v2-field">Data<input v-model="b.historyDate" type="date" /></label><label class="v2-field">Stato<select v-model="b.historyStatus"><option value="">Tutti gli stati</option><option v-for="status in ['new','in_preparazione','pronto','completato','annullato']" :key="status" :value="status">{{ b.statusLabel(status) }}</option></select></label><label class="v2-field">Cerca numero ordine<input v-model="b.historySearch" type="search" placeholder="Numero ordine" /></label></div><hr class="v2-divider" />
   <div v-if="!b.historyOrders.length" class="v2-empty">Nessun ordine corrisponde ai filtri.</div><div v-else class="v2-table-wrap"><table class="v2-table"><thead><tr><th>Ordine</th><th>Data</th><th>Cliente</th><th>Totale</th><th>Stato</th><th>Pagamento</th></tr></thead><tbody><tr v-for="order in b.historyOrders" :key="order.id"><td><button class="v2-link" @click="b.openOrderDetail(order)">#{{ order.id }}</button></td><td>{{ b.formatOrderTime(order.created_at, true) }}</td><td>{{ b.customerLabel(order) }}</td><td>€ {{ b.euro(order.total_cents) }}</td><td>{{ b.statusLabel(order.order_status) }}</td><td>{{ b.paymentLabel(order.payment_status) }}</td></tr></tbody></table></div>
  </V2Panel>

  <template v-else-if="b.activeTab === 'menu'">
   <div class="v2-grid-2"><V2Panel title="Nuovo prodotto" description="Aggiungi un prodotto e assegnalo a una categoria."><form class="v2-stack" @submit.prevent="c.run('bar-product-create', b.createProduct, 'Prodotto creato.')"><label class="v2-field">Nome *<input v-model="b.newProduct.name" required /></label><div class="v2-grid-2"><label class="v2-field">Prezzo (€) *<input v-model.number="b.newProduct.priceEuro" type="number" min="0.01" step="0.01" required /></label><label class="v2-field">Categoria *<select v-model.number="b.newProduct.categoryId" required><option :value="0" disabled>Seleziona categoria</option><option v-for="category in b.barCategories" :key="category.id" :value="category.id">{{ category.name }}</option></select></label></div><label class="v2-field">Descrizione<textarea v-model="b.newProduct.description" rows="2" /></label><label class="v2-field">Immagine<input type="file" accept="image/*" @change="c.run('bar-product-image', () => b.onProductImageSelect($event))" /></label><img v-if="b.newProduct.image_url" class="v2-image-preview" :src="b.newProduct.image_url" alt="Anteprima prodotto" /><p v-if="!b.barCategories.length" class="v2-notice">Crea una categoria per poter aggiungere un prodotto.</p><button class="v2-button v2-primary" :disabled="c.busy('bar-product-create') || !b.barCategories.length">Crea prodotto</button></form></V2Panel>
    <V2Panel title="Nuovo menù" description="Raggruppa i prodotti in un pacchetto."><form class="v2-stack" @submit.prevent="c.run('bar-menu-create', b.createMenu, 'Menù creato.')"><label class="v2-field">Nome *<input v-model="b.newMenu.name" required /></label><label class="v2-field">Prezzo menù (€) *<input v-model.number="b.newMenu.priceEuro" type="number" min="0.01" step="0.01" required /></label><label class="v2-field">Descrizione<textarea v-model="b.newMenu.description" rows="2" /></label><fieldset><legend>Prodotti inclusi *</legend><p v-if="!b.productCards.length" class="v2-muted">Crea almeno un prodotto.</p><div v-for="product in b.productCards" :key="product.id" class="v2-bar-row"><label class="v2-check"><input type="checkbox" :checked="b.isMenuProductSelected(product.id)" @change="b.toggleMenuProduct(product.id, $event.target.checked)" />{{ product.name }}</label><label class="v2-field v2-bar-qty"><span class="v2-muted">Quantità</span><input type="number" min="1" :disabled="!b.isMenuProductSelected(product.id)" :value="b.menuQty(product.id)" @input="b.setMenuQty(product.id, $event.target.value)" /></label></div></fieldset><button class="v2-button v2-primary" :disabled="c.busy('bar-menu-create') || !Object.values(b.newMenu.items).some(value => Number(value) > 0)">Crea menù</button></form></V2Panel></div>
   <V2Panel title="Catalogo prodotti"><div v-if="!b.productCards.length" class="v2-empty">Nessun prodotto nel catalogo.</div><div class="v2-grid-3"><article v-for="product in b.productCards" :key="product.id" class="v2-bar-product"><img v-if="product.image_url" :src="product.image_url" :alt="product.name" /><div class="v2-stack"><div><h3>{{ product.name }}</h3><p class="v2-muted">{{ product.category || 'Categoria non assegnata' }}</p></div><strong>€ {{ b.euro(product.price_cents) }}</strong><p>{{ product.description || 'Nessuna descrizione' }}</p><button class="v2-button v2-danger" @click="remove('product', product)">Elimina prodotto</button></div></article></div></V2Panel>
   <V2Panel title="Menù disponibili"><div v-if="!b.barMenus.length" class="v2-empty">Nessun menù creato.</div><div v-for="menu in b.barMenus" :key="menu.id" class="v2-bar-row"><div><h3>{{ menu.name }}</h3><p class="v2-muted">{{ menu.description || 'Nessuna descrizione' }} · {{ (menu.items || []).length }} prodotti</p></div><strong>€ {{ b.euro(menu.price_cents) }}</strong><button class="v2-button v2-danger" @click="remove('menu', menu)">Elimina menù</button></div></V2Panel>
  </template>

  <template v-else-if="b.activeTab === 'categories'">
   <V2Panel :title="b.editingCategoryId ? 'Modifica categoria' : 'Nuova categoria'"><form class="v2-stack" @submit.prevent="c.run('bar-category-save', b.saveCategory, 'Categoria salvata.')"><div class="v2-grid-2"><label class="v2-field">Nome *<input v-model="b.newCategory.name" required /></label><label class="v2-field">Immagine *<input type="file" accept="image/*" :required="!b.newCategory.image_url" @change="c.run('bar-category-image', () => b.onCategoryImageSelect($event))" /></label></div><img v-if="b.newCategory.image_url" class="v2-image-preview" :src="b.newCategory.image_url" alt="Anteprima categoria" /><div class="v2-toolbar"><button class="v2-button v2-primary" :disabled="c.busy('bar-category-save')">{{ b.editingCategoryId ? 'Salva modifiche' : 'Crea categoria' }}</button><button v-if="b.editingCategoryId" class="v2-button" type="button" @click="b.resetCategoryForm">Annulla modifica</button></div></form></V2Panel>
   <V2Panel title="Categorie"><div v-if="!b.barCategories.length" class="v2-empty">Nessuna categoria disponibile.</div><div v-for="category in b.barCategories" :key="category.id" class="v2-bar-row"><img class="v2-image-preview" :src="category.image_url" :alt="category.name" /><strong>{{ category.name }}</strong><div class="v2-toolbar"><button class="v2-button" @click="b.editCategory(category)">Modifica</button><button class="v2-button v2-danger" @click="remove('category', category)">Elimina</button></div></div></V2Panel>
  </template>

  <template v-else-if="b.activeTab === 'suggestions'">
   <V2Panel title="Suggerimenti nel carrello" description="I suggerimenti del prodotto hanno priorità; la categoria viene usata come alternativa. Seleziona fino a tre prodotti."><label class="v2-field">Configura per<select v-model="suggestionScope"><option value="products">Prodotto</option><option value="categories">Categoria</option></select></label></V2Panel>
   <div v-if="!suggestionEntities.length" class="v2-empty">Aggiungi prima {{ suggestionScope === 'products' ? 'un prodotto' : 'una categoria' }}.</div>
   <V2Panel v-for="entity in suggestionEntities" :key="`${suggestionScope}-${entity.id}`" :title="entity.name"><div class="v2-stack"><label class="v2-check"><input type="checkbox" :checked="suggestion(entity).enabled" @change="patchSuggestion(entity, 'enabled', $event.target.checked)" />Attiva suggerimenti</label><div class="v2-grid-2"><label class="v2-field">Titolo del riquadro<input :value="suggestion(entity).title" @input="patchSuggestion(entity, 'title', $event.target.value)" /></label><label class="v2-field">Numero massimo mostrato<select :value="suggestion(entity).max_items" @change="patchSuggestion(entity, 'max_items', $event.target.value)"><option :value="2">2 prodotti</option><option :value="3">3 prodotti</option></select></label></div><fieldset><legend>Prodotti consigliati</legend><div class="v2-grid-3"><label v-for="candidate in b.productCards.filter(item => suggestionScope === 'categories' || item.id !== entity.id)" :key="candidate.id" class="v2-check"><input type="checkbox" :checked="suggestion(entity).suggestion_ids.includes(candidate.id)" :disabled="!suggestion(entity).suggestion_ids.includes(candidate.id) && suggestion(entity).suggestion_ids.length >= 3" @change="toggleSuggestion(entity, candidate, $event.target.checked)" />{{ candidate.name }}</label></div></fieldset><div><button class="v2-button v2-primary" :disabled="c.busy(`bar-suggestion-${entity.id}`)" @click="saveSuggestion(entity)">Salva suggerimenti</button></div></div></V2Panel>
  </template>

  <V2Panel v-else-if="b.activeTab === 'quick'" title="Disponibilità rapida" description="Questa selezione resta soltanto nella sessione di questo pannello. Il servizio esistente non salva la disponibilità né aggiorna il catalogo dei tifosi."><div v-if="!b.productCards.length" class="v2-empty">Nessun prodotto disponibile.</div><div v-for="product in b.productCards" :key="product.id" class="v2-bar-row"><div><h3>{{ product.name }}</h3><span class="v2-badge" :class="product.available ? 'success' : 'warning'">{{ product.available ? 'Disponibile nel pannello' : 'Esaurito nel pannello' }}</span></div><div class="v2-toolbar"><button class="v2-button" :class="{ 'v2-primary': product.available }" :aria-pressed="product.available" @click="b.setProductAvailability(product.id, true)">Disponibile</button><button class="v2-button" :class="{ 'v2-danger': !product.available }" :aria-pressed="!product.available" @click="b.setProductAvailability(product.id, false)">Esaurito</button></div></div></V2Panel>

  <div v-else-if="b.activeTab === 'clients'" class="v2-grid-2"><V2Panel title="Clienti"><p v-if="!b.clientRows.length" class="v2-empty">Nessun cliente negli ordini disponibili.</p><button v-for="client in b.clientRows" :key="client.id" class="v2-bar-client" :aria-pressed="b.selectedClientId === client.id" @click="b.selectedClientId = client.id"><strong>{{ client.name }}</strong><span>{{ client.orders }} ordini · € {{ b.euro(client.totalCents) }}</span><small>Ultimo ordine {{ b.formatOrderTime(client.lastOrderAt, true) }}</small></button></V2Panel><V2Panel :title="b.selectedClient?.name || 'Storico cliente'"><div v-if="!b.selectedClient" class="v2-empty">Seleziona un cliente per visualizzare i suoi ordini.</div><template v-else><p class="v2-notice">{{ b.selectedClient.orders }} ordini · Totale € {{ b.euro(b.selectedClient.totalCents) }}</p><div v-for="order in b.selectedClientOrders" :key="order.id" class="v2-bar-row"><button class="v2-link" @click="b.openOrderDetail(order)">#{{ order.id }} · {{ b.formatOrderTime(order.created_at, true) }}</button><span>{{ b.statusLabel(order.order_status) }}</span><strong>€ {{ b.euro(order.total_cents) }}</strong></div></template></V2Panel></div>

  <div v-else-if="b.activeTab === 'settings'" class="v2-grid-2"><V2Panel title="Contesto del servizio"><dl class="v2-bar-details"><dt>Società</dt><dd>{{ c.organizationName || c.organizationSlug }}</dd><dt>Accesso</dt><dd>{{ c.isSuperAdmin ? 'Amministratore' : 'Operatore bar' }}</dd></dl><p class="v2-muted">Gli ordini e il catalogo seguono il perimetro consentito dal tuo account.</p></V2Panel><V2Panel title="Preferenze del pannello" description="Preferenze locali, ripristinate alla chiusura della sezione. Nessuna impostazione viene salvata sul server."><label class="v2-check"><input v-model="b.settings.autoRefreshLive" type="checkbox" />Aggiorna automaticamente ogni 15 secondi</label><label class="v2-check"><input v-model="b.settings.notifyNewOrders" type="checkbox" />Preferenza notifiche nuovi ordini</label><label class="v2-check"><input v-model="b.settings.soundAlerts" type="checkbox" />Preferenza avvisi sonori</label><p class="v2-notice">Le preferenze di notifica e audio sono conservate localmente dal pannello esistente; non attivano un servizio di avvisi.</p></V2Panel></div>

  <V2Dialog :open="Boolean(b.selectedOrder)" :title="b.selectedOrder ? `Ordine #${b.selectedOrder.id}` : 'Dettaglio ordine'" @close="b.closeOrderDetail"><template v-if="b.selectedOrder"><div class="v2-toolbar"><span class="v2-badge">{{ b.statusLabel(b.selectedOrder.order_status) }}</span><span class="v2-badge" :class="b.paymentClass(b.selectedOrder.payment_status) === 'ok' ? 'success' : 'warning'">{{ b.paymentLabel(b.selectedOrder.payment_status) }}</span><strong>€ {{ b.euro(b.selectedOrder.total_cents) }}</strong></div><dl class="v2-bar-details"><dt>Cliente</dt><dd>{{ b.customerLabel(b.selectedOrder) }}</dd><dt>Posizione</dt><dd>{{ b.seatingLabel(b.selectedOrder) }}</dd><dt>Creato</dt><dd>{{ b.formatOrderTime(b.selectedOrder.created_at, true) }}</dd><dt>Aggiornato</dt><dd>{{ b.formatOrderTime(b.selectedOrder.updated_at, true) }}</dd></dl><V2Panel title="Prodotti ordinati"><p v-if="!b.selectedOrder.parsedItems?.length" class="v2-muted">Dettaglio prodotti non disponibile.</p><div v-for="item in b.selectedOrder.parsedItems" :key="item.id" class="v2-bar-row"><span><strong>{{ item.quantity }} ×</strong> {{ item.name }}</span><span>€ {{ b.euro(item.priceCents) }} cad.</span></div></V2Panel><V2Panel title="Note"><p>{{ b.selectedOrder.notes || 'Nessuna nota per questo ordine.' }}</p></V2Panel></template><template #footer><button class="v2-button" @click="b.closeOrderDetail">Chiudi dettaglio</button></template></V2Dialog>
 </div>
</template>

<style scoped>
